    self.job, self.result, self.context = nil, nil, nil
    self.generation = self.generation + 1
    return result
end--[[APR_DIAG]]; Host.Cancel = APRTrace("APR-Core/features/navigation/NavigationV2.lua:180:Host:Cancel#23", Host.Cancel)--[[/APR_DIAG]]

